#!/usr/bin/env node
/*
 * DFO Online mods - one sync for the whole workspace.
 *
 * Autosync (and `--if-needed` by hand) runs this after the game store or the
 * launcher config changes: it re-installs the loader, then runs every mod
 * installer listed in modloader/mods.json with `--if-needed`.
 *
 * A fresh checkout has no mods.json (it is generated by the installers), so
 * when the manifest is empty this discovers every ../*-mod/install.mjs beside
 * the loader and installs those instead; they write the manifest for next time.
 *
 * Each installer is idempotent and exits 0 when healthy, 2 when there is
 * nothing patchable right now (no mounted seed) - both are success here.
 * A real failure (exit 1, a crash) is reported and makes this exit 1.
 */
'use strict';

import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { MODLOADER_ROOT } from './lib/store.mjs';
import { readManifest, manifestDir } from './lib/registry.mjs';

const QUIET = process.argv.includes('--quiet');
const say = (...a) => { if (!QUIET) console.log(...a); };

/* A portable install can only be found while it runs; install.bat/install.sh
 * persist the path it was given, and the scheduled task (which has no shell
 * environment of its own) reads it back through this file. */
const APP_FILE = path.join(MODLOADER_ROOT, 'app-path.txt');
try {
  if (!process.env.DFO_APP) {
    const app = fs.readFileSync(APP_FILE, 'utf8').trim();
    if (app) process.env.DFO_APP = app;
  }
} catch { /* no override - the usual discovery */ }

const run = (script, cwd, ifNeeded = true) => {
  const flags = [...(ifNeeded ? ['--if-needed'] : []), ...(QUIET ? ['--quiet'] : [])];
  const r = spawnSync(process.execPath, [script, ...flags], {
    cwd, stdio: 'inherit', env: process.env,
  });
  if (r.error) { console.error(`[dfo-mods] ${script}: ${r.error.message}`); return 1; }
  return r.status == null ? 1 : r.status;
};

/** The mods beside the loader, for a workspace whose manifest is not written
 *  yet. Their installers create modloader/mods.json as they register. */
function discoverMods() {
  const root = path.dirname(MODLOADER_ROOT);
  let names = [];
  try { names = fs.readdirSync(root); } catch { return []; }
  const out = [];
  for (const name of names.sort()) {
    const dir = path.join(root, name);
    if (dir === MODLOADER_ROOT) continue;
    try { if (!fs.statSync(dir).isDirectory()) continue; } catch { continue; }
    if (fs.existsSync(path.join(dir, 'install.mjs'))) out.push({ id: name, name, dir: `../${name}` });
  }
  return out;
}

const failed = [];

say('[dfo-mods] sync');
const loader = path.join(MODLOADER_ROOT, 'install.mjs');
let code = run(loader, MODLOADER_ROOT);
if (code !== 0 && code !== 2) failed.push('loader');

let mods = readManifest();
const discovered = !mods.length;
if (discovered) {
  mods = discoverMods();
  if (mods.length) say(`[dfo-mods] no manifest yet - discovered ${mods.map((m) => m.id).join(', ')}`);
  else say('[dfo-mods] no mods to install here (no mods.json and no ../*-mod/install.mjs)');
}

for (const mod of mods) {
  const dir = manifestDir(mod);
  const script = path.join(dir, 'install.mjs');
  if (!fs.existsSync(script)) {
    console.error(`[dfo-mods] ${mod.id}: no installer at ${script} (stale modloader/mods.json entry)`);
    failed.push(mod.id);
    continue;
  }
  say(`[dfo-mods] ${mod.id}`);
  // a discovered mod runs without --if-needed so it registers itself in the
  // manifest; from then on sync uses the fast path
  code = run(script, dir, !discovered);
  if (code !== 0 && code !== 2) failed.push(mod.id);
}

if (failed.length) {
  console.error(`[dfo-mods] failed: ${failed.join(', ')}`);
  process.exit(1);
}
say('[dfo-mods] sync done');
